			/* <flatten type="Javascript"> */
function load$GridDetail$d3(g) {
	g.add_itemValueChanged(onChange$GridDetail$d3);
	g.add_commandEvent(on$GridDetail$d3$ExecuteCommand);
	g.$a = {
		_1t_tl_tien_da_chi: ['_1t_tl_tien_da_chi', 'tien_da_chi']
		, _1t_tl_tien_con_lai: '[_1t_tl_tien_con_lai]:=[_1da_tt]-([_1t_tl_tien_da_chi])'
	};
}
function dispose$GridDetail$d3(g) {
	try {g.remove_commandEvent(on$GridDetail$d3$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridDetail$d3);} catch (ex) {}
}
/* </flatten> */
function on$GridDetail$d3$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		&GridExtraToolbarExecuteCommandScript;
		case 'AfterRemoveRow':
			on$GridDetail$d3$RowChange(g, f);
			break;
		case 'AfterInsertRow':
			on$GridDetail$d3$RowChange(g, f);
			break;
		default:
			break;
	}
}
function onChange$GridDetail$d3(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		default:
			break;
	}
}
function on$GridDetail$d3$RowChange(g, f) {
	on$GridDetail$d3$Calculate(g, f);
	g.executeAggregate([g.$a._1t_tl_tien_da_chi]);
	f.executeExpression([g.$a._1t_tl_tien_con_lai]);
}
function on$GridDetail$d3$Calculate(g, f) {
	var _1da_tt = f.getItemValue('_1da_tt');
	for (var r = 1; r <= g._rowCount; r++) {
		g._setItemValue(r, g._getColumnOrder('tien_con_lai'), 0);
		var tien_da_chi = 0;
		for (rr = 1; rr < r; rr++) tien_da_chi += g._getItemValue(rr, g._getColumnOrder('tien_da_chi'));
		g._setItemValue(r, g._getColumnOrder('tien_con_lai'), _1da_tt - (tien_da_chi + g._getItemValue(r, g._getColumnOrder('tien_da_chi'))));
	}
}

			&GridExtraToolbarScript;
